<tr><td>Cho thuê dài hạn</td><td>Hợp – studio 31,6 m² hoặc 1PN+ 54,2 m²</td></tr>
<tr><td>Kinh doanh</td><td>Shophouse tầng 1, mặt tiền khoảng 6,2 – 7,5 m</td></tr>
